import heapq

def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in set(edges):
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for _, w in items:
        if w <= 0 or w > limit:
            raise ValueError("Invalid weight")

    batches = []
    current_batch = []
    current_weight = 0

    for name, w in items:
        if current_weight + w > limit:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = w
        else:
            current_batch.append(name)
            current_weight += w

    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    env = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid assignment line: {line}")
        key, value = line.split('=', 1)
        key = key.strip()
        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key}")
        value = value.strip()
        if len(value) >= 2:
            if (value[0] == '"' and value[-1] == '"') or \
               (value[0] == "'" and value[-1] == "'"):
                value = value[1:-1]
        env[key] = value
    return env

