import re

def parse_sse(chunks):
    decoder = codecs.getincrementaldecoder('utf-8')()
    text_parts = []
    for chunk in chunks:
        text_parts.append(decoder.decode(chunk, final=False))
    text_parts.append(decoder.decode(b'', final=True))
    text = ''.join(text_parts)

    results = []
    current_data = []

    for line in re.split(r'\r?\n', text):
        if not line:
            if current_data:
                event_data = '\n'.join(current_data)
                if event_data == '[DONE]':
                    return results
                results.append(event_data)
                current_data = []
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            current_data.append(value)

    return results

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be non-negative")
    if base == 0 or cap == 0:
        return 0.0
    # Compute the attempt number at which base * 2**attempt reaches cap.
    # Using log2(cap) - log2(base) avoids overflow when computing cap/base.
    threshold = math.log2(cap) - math.log2(base)
    if attempt >= threshold:
        return float(cap)
    return base * (2 ** attempt)

def fifo_admit(active, queued, budget, slots):
    for req in queued:
        if req > budget:
            raise ValueError("Queued reservation exceeds budget")

    admitted = []
    curr_sum = sum(active)
    curr_slots = len(active)

    for i, req in enumerate(queued):
        if curr_slots + 1 <= slots and curr_sum + req <= budget:
            admitted.append(req)
            curr_sum += req
            curr_slots += 1
        else:
            return admitted, queued[i:]

    return admitted, []
